import { seededRandom } from "../components/planet-palette";

const PREFIXES = [
  "R",
  "KAI",
  "NOVA",
  "PICO",
  "ORB",
  "VEGA",
  "ATLAS",
  "IRIS",
  "ECHO",
  "LUX",
];

/**
 * Designation of the robot sent to a planet, e.g. "NOVA-3". Derived from the seed
 * (the planet name), so a planet always has the same robot. A stand-in until the
 * robots generated by the RAG system are stored with the planets.
 */
export function robotDesignation(seed: string) {
  const random = seededRandom(`robot:${seed}`);
  const prefix = PREFIXES[Math.floor(random() * PREFIXES.length)];
  return `${prefix}-${1 + Math.floor(random() * 9)}`;
}
